function readMeetingForm(modal,existing={}){const start=new Date(modal.querySelector('#meetStart').value),end=new Date(modal.querySelector('#meetEnd').value),provider=modal.querySelector('#meetProvider').value,joinUrl=modal.querySelector('#meetUrl').value.trim(),title=modal.querySelector('#meetTitle').value.trim();if(!title){toast('Add an event title','warning');return null;}if(!start.getTime()||!end.getTime()||end<=start){toast('Event end time must be after the start time','warning');return null;}if(provider!=='none'&&!/^https:\/\//i.test(joinUrl)){toast('Add a valid https meeting link','warning');return null;}return{...existing,title,start:start.toISOString(),end:end.toISOString(),timezone:modal.querySelector('#meetTimezone').value.trim()||'Europe/Berlin',allDay:modal.querySelector('#meetAllDay').checked,requiredAttendees:modal.querySelector('#meetRequired').value.trim(),optionalAttendees:modal.querySelector('#meetOptional').value.trim(),organizerAccountId:modal.querySelector('#meetOrganizer').value||null,provider,joinUrl,location:modal.querySelector('#meetLocation').value.trim(),notes:modal.querySelector('#meetNotes').value.trim(),recurrence:modal.querySelector('#meetRecurrence').value,reminders:[...modal.querySelector('#meetReminder').selectedOptions].map(x=>Number(x.value)),showAs:modal.querySelector('#meetShowAs').value,responseRequested:modal.querySelector('#meetResponses').checked,status:existing.status||'draft',method:existing.method||'REQUEST'};}
function prepareMeetingModal(modal,existing){const provider=modal.querySelector('#meetProvider'),urlField=modal.querySelector('#meetingUrlField');provider.value=existing?.provider||'none';modal.querySelector('#meetShowAs').value=existing?.showAs||'busy';modal.querySelector('#meetRecurrence').value=existing?.recurrence||'';[...modal.querySelector('#meetReminder').options].forEach(o=>o.selected=(existing?.reminders||[15]).includes(Number(o.value)));const update=()=>urlField.classList.toggle('hidden',provider.value==='none');provider.onchange=update;update();}
function attachMeetingToComposer(meeting){const c=state.composer?.el;if(!c)return;state.composer.meeting=meeting;const req=splitAddr(meeting.requiredAttendees),opt=splitAddr(meeting.optionalAttendees);if(req.length&&!c.querySelector('#cTo').value.trim())c.querySelector('#cTo').value=req.join(', ');if(opt.length&&!c.querySelector('#cCc').value.trim())c.querySelector('#cCc').value=opt.join(', ');if(!c.querySelector('#cSubject').value.trim())c.querySelector('#cSubject').value=(meeting.method==='CANCEL'?'Cancelled: ':'')+meeting.title;const editor=c.querySelector('#cEditor');editor.querySelectorAll('[data-ff-meeting]').forEach(x=>x.remove());editor.insertAdjacentHTML('afterbegin',`${renderMeetingCard(meeting)}<br>`);scheduleAutosave();}
